export const SEARCH_GRAMMAR_VERSION = 1 as const;

/** UTF-16 source offsets, with an inclusive start and exclusive end. */
export interface SourceRange {
  readonly start: number;
  readonly end: number;
}

export type SearchParseErrorCode =
  | "UNMATCHED_QUOTE"
  | "EMPTY_PHRASE"
  | "EMPTY_TAG"
  | "MISSING_LEFT_OPERAND"
  | "MISSING_RIGHT_OPERAND"
  | "DOUBLE_OPERATOR"
  | "UNSUPPORTED_GROUPING"
  | "UNSUPPORTED_NEGATION"
  | "INVALID_ESCAPE";

export interface SearchParseError {
  readonly code: SearchParseErrorCode;
  readonly message: string;
  readonly hint: string;
  readonly range: SourceRange;
}

export interface EmptySearchNode {
  readonly kind: "Empty";
}

export interface TextSearchNode {
  readonly kind: "Text";
  readonly value: string;
  readonly range: SourceRange;
}

export interface PhraseSearchNode {
  readonly kind: "Phrase";
  readonly value: string;
  readonly range: SourceRange;
}

export interface TagSearchNode {
  readonly kind: "Tag";
  readonly normalizedValue: string;
  readonly displayValue: string;
  readonly range: SourceRange;
}

export interface AndSearchNode {
  readonly kind: "And";
  readonly left: SearchExpression;
  readonly right: SearchExpression;
  readonly range: SourceRange;
}

export interface OrSearchNode {
  readonly kind: "Or";
  readonly left: SearchExpression;
  readonly right: SearchExpression;
  readonly range: SourceRange;
}

export type SearchExpression =
  | TextSearchNode
  | PhraseSearchNode
  | TagSearchNode
  | AndSearchNode
  | OrSearchNode;

export type SearchAst = EmptySearchNode | SearchExpression;

export type SearchParseResult =
  | { readonly ok: true; readonly ast: SearchAst }
  | { readonly ok: false; readonly error: SearchParseError };

export type SearchToken =
  | {
      readonly kind: "text";
      readonly value: string;
      readonly range: SourceRange;
    }
  | {
      readonly kind: "phrase";
      readonly value: string;
      readonly range: SourceRange;
    }
  | {
      readonly kind: "tag";
      readonly normalizedValue: string;
      readonly displayValue: string;
      readonly range: SourceRange;
    }
  | { readonly kind: "and"; readonly range: SourceRange }
  | { readonly kind: "or"; readonly range: SourceRange };

export type SearchTokenizeResult =
  | { readonly ok: true; readonly tokens: readonly SearchToken[] }
  | { readonly ok: false; readonly error: SearchParseError };

export class SearchQuerySyntaxError extends Error {
  readonly code: SearchParseErrorCode;
  readonly hint: string;
  readonly range: SourceRange;

  constructor(readonly detail: SearchParseError) {
    super(detail.message);
    this.name = "SearchQuerySyntaxError";
    this.code = detail.code;
    this.hint = detail.hint;
    this.range = detail.range;
  }
}
import { searchParseError, tokenizeSearchQuery } from "./tokenizer.js";
import {
  type AndSearchNode,
  type EmptySearchNode,
  type OrSearchNode,
  type SearchAst,
  type SearchExpression,
  type SearchParseError,
  type SearchParseResult,
  SearchQuerySyntaxError,
  type SearchToken,
  type SourceRange,
} from "./types.js";

const EMPTY: EmptySearchNode = Object.freeze({ kind: "Empty" });

function sourceRange(start: number, end: number): SourceRange {
  return Object.freeze({ start, end });
}

function expressionRange(expression: SearchExpression): SourceRange {
  return expression.range;
}

function atomFromToken(token: SearchToken): SearchExpression {
  switch (token.kind) {
    case "text":
      return Object.freeze({ kind: "Text", value: token.value, range: token.range });
    case "phrase":
      return Object.freeze({ kind: "Phrase", value: token.value, range: token.range });
    case "tag":
      return Object.freeze({
        kind: "Tag",
        displayValue: token.displayValue,
        normalizedValue: token.normalizedValue,
        range: token.range,
      });
    case "and":
    case "or":
      throw new Error("An operator cannot be converted to a search atom.");
  }
}

function andNode(left: SearchExpression, right: SearchExpression): AndSearchNode {
  return Object.freeze({
    kind: "And",
    left,
    right,
    range: sourceRange(expressionRange(left).start, expressionRange(right).end),
  });
}

function orNode(left: SearchExpression, right: SearchExpression): OrSearchNode {
  return Object.freeze({
    kind: "Or",
    left,
    right,
    range: sourceRange(expressionRange(left).start, expressionRange(right).end),
  });
}

function isOperator(
  token: SearchToken | undefined,
): token is Extract<SearchToken, { kind: "and" | "or" }> {
  return token?.kind === "and" || token?.kind === "or";
}

function isParseError(value: SearchExpression | SearchParseError): value is SearchParseError {
  return "code" in value;
}

class Parser {
  private cursor = 0;

  constructor(private readonly tokens: readonly SearchToken[]) {}

  parse(): SearchExpression | SearchParseError {
    const first = this.peek();
    if (first === undefined) throw new Error("Parser requires at least one token.");
    if (isOperator(first)) {
      return searchParseError("MISSING_LEFT_OPERAND", first.range.start, first.range.end);
    }

    let expression = this.parseAnd();
    if (isParseError(expression)) return expression;

    while (this.peek()?.kind === "or") {
      const operator = this.consume();
      const next = this.peek();
      if (next === undefined) {
        return searchParseError("MISSING_RIGHT_OPERAND", operator.range.start, operator.range.end);
      }
      if (isOperator(next)) {
        return searchParseError("DOUBLE_OPERATOR", next.range.start, next.range.end);
      }

      const right = this.parseAnd();
      if (isParseError(right)) return right;
      expression = orNode(expression, right);
    }

    return expression;
  }

  private parseAnd(): SearchExpression | SearchParseError {
    const first = this.consume();
    let expression = atomFromToken(first);

    while (true) {
      const token = this.peek();
      if (token === undefined || token.kind === "or") return expression;

      if (token.kind === "and") {
        const operator = this.consume();
        const next = this.peek();
        if (next === undefined) {
          return searchParseError(
            "MISSING_RIGHT_OPERAND",
            operator.range.start,
            operator.range.end,
          );
        }
        if (isOperator(next)) {
          return searchParseError("DOUBLE_OPERATOR", next.range.start, next.range.end);
        }
      }

      const rightToken = this.consume();
      if (isOperator(rightToken)) {
        return searchParseError("DOUBLE_OPERATOR", rightToken.range.start, rightToken.range.end);
      }
      expression = andNode(expression, atomFromToken(rightToken));
    }
  }

  private peek(): SearchToken | undefined {
    return this.tokens[this.cursor];
  }

  private consume(): SearchToken {
    const token = this.tokens[this.cursor];
    if (token === undefined) throw new Error("Unexpected end of token stream.");
    this.cursor += 1;
    return token;
  }
}

export function parseSearchQuery(source: string): SearchParseResult {
  const tokenized = tokenizeSearchQuery(source);
  if (!tokenized.ok) return tokenized;
  if (tokenized.tokens.length === 0) return Object.freeze({ ok: true, ast: EMPTY });

  const parsed = new Parser(tokenized.tokens).parse();
  if (isParseError(parsed)) {
    return Object.freeze({ ok: false, error: parsed });
  }
  return Object.freeze({ ok: true, ast: parsed });
}

export function parseSearchQueryOrThrow(source: string): SearchAst {
  const result = parseSearchQuery(source);
  if (!result.ok) throw new SearchQuerySyntaxError(result.error);
  return result.ast;
}
import type {
  SearchParseError,
  SearchParseErrorCode,
  SearchToken,
  SearchTokenizeResult,
  SourceRange,
} from "./types.js";

const HINTS = {
  UNMATCHED_QUOTE: "Close the quoted phrase",
  EMPTY_PHRASE: "Add text inside the quotes",
  EMPTY_TAG: "Add a tag name after `#`",
  MISSING_LEFT_OPERAND: "Add a search term before the operator",
  MISSING_RIGHT_OPERAND: "Add a search term after the operator",
  DOUBLE_OPERATOR: "Remove one operator or add a term between them",
  UNSUPPORTED_GROUPING: "Remove parentheses; `AND` already binds before `OR`",
  UNSUPPORTED_NEGATION: "Negation is not supported",
  INVALID_ESCAPE: "Escape only a quote or backslash",
} as const satisfies Record<SearchParseErrorCode, string>;

const MESSAGES = {
  UNMATCHED_QUOTE: "The quoted phrase is not closed.",
  EMPTY_PHRASE: "A quoted phrase must contain text.",
  EMPTY_TAG: "An exact tag expression must include a tag name.",
  MISSING_LEFT_OPERAND: "The operator needs a search term before it.",
  MISSING_RIGHT_OPERAND: "The operator needs a search term after it.",
  DOUBLE_OPERATOR: "Two operators cannot appear together.",
  UNSUPPORTED_GROUPING: "Parentheses are not supported in search grammar version 1.",
  UNSUPPORTED_NEGATION: "Negation is not supported in search grammar version 1.",
  INVALID_ESCAPE: "Quoted text can escape only a quote or backslash.",
} as const satisfies Record<SearchParseErrorCode, string>;

function sourceRange(start: number, end: number): SourceRange {
  return Object.freeze({ start, end });
}

export function searchParseError(
  code: SearchParseErrorCode,
  start: number,
  end: number,
): SearchParseError {
  return Object.freeze({
    code,
    message: MESSAGES[code],
    hint: HINTS[code],
    range: sourceRange(start, end),
  });
}

/**
 * Normalization used for exact tag identity. Display spelling is deliberately
 * kept separate by tag tokens.
 */
export function normalizeExactTag(value: string): string {
  return value.normalize("NFKC").replace(/\s+/gu, " ").trim().toLocaleLowerCase("und");
}

function cleanTagDisplay(value: string): string {
  return value.replace(/\s+/gu, " ").trim();
}

interface QuotedSuccess {
  readonly ok: true;
  readonly value: string;
  readonly end: number;
}

interface QuotedFailure {
  readonly ok: false;
  readonly error: SearchParseError;
}

function readQuoted(source: string, quoteStart: number): QuotedSuccess | QuotedFailure {
  const decoded: string[] = [];
  let cursor = quoteStart + 1;

  while (cursor < source.length) {
    const character = source[cursor];
    if (character === '"') {
      return { ok: true, value: decoded.join(""), end: cursor + 1 };
    }

    if (character === "\\") {
      const escaped = source[cursor + 1];
      if (escaped === undefined) {
        return { ok: false, error: searchParseError("INVALID_ESCAPE", cursor, cursor + 1) };
      }
      if (escaped !== '"' && escaped !== "\\") {
        return { ok: false, error: searchParseError("INVALID_ESCAPE", cursor, cursor + 2) };
      }
      decoded.push(escaped);
      cursor += 2;
      continue;
    }

    decoded.push(character ?? "");
    cursor += 1;
  }

  return {
    ok: false,
    error: searchParseError("UNMATCHED_QUOTE", quoteStart, source.length),
  };
}

function frozenToken<T extends SearchToken>(token: T): T {
  return Object.freeze(token);
}

function isWhitespace(character: string | undefined): boolean {
  return character !== undefined && /\s/u.test(character);
}

function operatorKind(value: string): "and" | "or" | null {
  const normalized = value.toLocaleUpperCase("en-US");
  if (normalized === "AND") return "and";
  if (normalized === "OR") return "or";
  return null;
}

/** A linear lexer for the deliberately small, non-grouping grammar. */
export function tokenizeSearchQuery(source: string): SearchTokenizeResult {
  const tokens: SearchToken[] = [];
  let cursor = 0;

  while (cursor < source.length) {
    if (isWhitespace(source[cursor])) {
      cursor += 1;
      continue;
    }

    const start = cursor;
    const character = source[cursor];

    if (character === "(" || character === ")") {
      return {
        ok: false,
        error: searchParseError("UNSUPPORTED_GROUPING", start, start + 1),
      };
    }

    if (character === '"') {
      const quoted = readQuoted(source, start);
      if (!quoted.ok) return quoted;
      if (quoted.value.trim() === "") {
        return {
          ok: false,
          error: searchParseError("EMPTY_PHRASE", start, quoted.end),
        };
      }
      tokens.push(
        frozenToken({
          kind: "phrase",
          value: quoted.value,
          range: sourceRange(start, quoted.end),
        }),
      );
      cursor = quoted.end;
      continue;
    }

    if (character === "#") {
      cursor += 1;
      if (cursor >= source.length || isWhitespace(source[cursor])) {
        return { ok: false, error: searchParseError("EMPTY_TAG", start, start + 1) };
      }

      let rawValue: string;
      if (source[cursor] === '"') {
        const quoted = readQuoted(source, cursor);
        if (!quoted.ok) return quoted;
        rawValue = quoted.value;
        cursor = quoted.end;
        if (rawValue.trim() === "") {
          return { ok: false, error: searchParseError("EMPTY_TAG", start, cursor) };
        }
      } else {
        const valueStart = cursor;
        while (
          cursor < source.length &&
          !isWhitespace(source[cursor]) &&
          source[cursor] !== "(" &&
          source[cursor] !== ")"
        ) {
          cursor += 1;
        }
        rawValue = source.slice(valueStart, cursor);
        if (rawValue === "") {
          return { ok: false, error: searchParseError("EMPTY_TAG", start, start + 1) };
        }
      }

      const displayValue = cleanTagDisplay(rawValue);
      tokens.push(
        frozenToken({
          kind: "tag",
          displayValue,
          normalizedValue: normalizeExactTag(displayValue),
          range: sourceRange(start, cursor),
        }),
      );
      continue;
    }

    while (
      cursor < source.length &&
      !isWhitespace(source[cursor]) &&
      source[cursor] !== '"' &&
      source[cursor] !== "(" &&
      source[cursor] !== ")"
    ) {
      cursor += 1;
    }
    const value = source.slice(start, cursor);

    if (value.startsWith("-")) {
      return {
        ok: false,
        error: searchParseError("UNSUPPORTED_NEGATION", start, cursor),
      };
    }
    if (value.toLocaleUpperCase("en-US") === "NOT") {
      return {
        ok: false,
        error: searchParseError("UNSUPPORTED_NEGATION", start, cursor),
      };
    }

    const kind = operatorKind(value);
    const tokenRange = sourceRange(start, cursor);
    tokens.push(
      kind === null
        ? frozenToken({ kind: "text", value, range: tokenRange })
        : frozenToken({ kind, range: tokenRange }),
    );
  }

  return Object.freeze({ ok: true, tokens: Object.freeze(tokens) });
}
import fs from "node:fs";
import path from "node:path";
import Database from "better-sqlite3";

export type AppDatabase = Database.Database;

export function openDatabase(databasePath: string): AppDatabase {
  if (databasePath !== ":memory:") {
    fs.mkdirSync(path.dirname(databasePath), { recursive: true });
  }

  const database = new Database(databasePath);
  database.pragma("foreign_keys = ON");
  database.pragma("busy_timeout = 5000");
  if (databasePath !== ":memory:") {
    database.pragma("journal_mode = WAL");
    database.pragma("synchronous = NORMAL");
  }
  return database;
}

export function closeDatabase(database: AppDatabase): void {
  if (database.open) database.close();
}
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { type AppDatabase, closeDatabase, openDatabase } from "../../src/server/db/database.js";
import { runMigrations } from "../../src/server/db/migrate.js";

const DEFAULT_MIGRATIONS_DIRECTORY = fileURLToPath(new URL("../../migrations/", import.meta.url));

export interface TestDatabaseOptions {
  migrate?: boolean;
  migrationsDirectory?: string;
  prefix?: string;
}

export interface TestDatabase {
  database: AppDatabase;
  databasePath: string;
  directory: string;
  appliedMigrations: readonly number[];
  cleanup: () => void;
}

/**
 * Creates a real, file-backed database so WAL, locking, and uniqueness behavior
 * match production. Every call owns a separate mkdtemp directory.
 */
export function createTestDatabase(options: TestDatabaseOptions = {}): TestDatabase {
  const directory = mkdtempSync(path.join(tmpdir(), options.prefix ?? "bookmark-garden-test-"));
  const databasePath = path.join(directory, "bookmarks.sqlite");
  const database = openDatabase(databasePath);
  let cleaned = false;

  try {
    const appliedMigrations =
      options.migrate === false
        ? []
        : runMigrations(database, options.migrationsDirectory ?? DEFAULT_MIGRATIONS_DIRECTORY);

    return {
      database,
      databasePath,
      directory,
      appliedMigrations,
      cleanup: () => {
        if (cleaned) return;
        cleaned = true;
        closeDatabase(database);
        rmSync(directory, { recursive: true, force: true });
      },
    };
  } catch (error) {
    closeDatabase(database);
    rmSync(directory, { recursive: true, force: true });
    throw error;
  }
}

export async function withTestDatabase<T>(
  run: (fixture: TestDatabase) => T | Promise<T>,
  options: TestDatabaseOptions = {},
): Promise<T> {
  const fixture = createTestDatabase(options);
  try {
    return await run(fixture);
  } finally {
    fixture.cleanup();
  }
}
