import type { TagSummary } from "../../shared/contracts/api.js";
import { normalizeExactTag } from "../../shared/search/tokenizer.js";
import type { AppDatabase } from "../db/database.js";

export interface NormalizedTagName {
  displayName: string;
  nameKey: string;
}

interface TagSummaryRow {
  id: number;
  name: string;
  activeBookmarkCount: number;
}

export class TagNameValidationError extends Error {
  readonly code = "INVALID_TAG_NAME";
  readonly field = "tag";

  constructor() {
    super("A tag name must contain at least one non-whitespace character.");
    this.name = "TagNameValidationError";
  }
}

/**
 * Preserves the user's spelling while deriving the Unicode-safe identity used
 * by both relational tag reads and exact `#tag` search expressions.
 */
export function normalizeTagName(value: string): NormalizedTagName {
  const displayName = value.replace(/\s+/gu, " ").trim();
  if (displayName === "") throw new TagNameValidationError();
  return { displayName, nameKey: normalizeExactTag(displayName) };
}

const SUMMARY_SELECT = `
  SELECT
    tags.id,
    tags.display_name AS name,
    count(
      CASE WHEN bookmarks.id IS NOT NULL AND bookmarks.archived_at IS NULL THEN 1 END
    ) AS activeBookmarkCount
  FROM tags
  LEFT JOIN bookmark_tags ON bookmark_tags.tag_id = tags.id
  LEFT JOIN bookmarks ON bookmarks.id = bookmark_tags.bookmark_id
`;

function toSummary(row: TagSummaryRow): TagSummary {
  return {
    id: row.id,
    name: row.name,
    activeBookmarkCount: row.activeBookmarkCount,
  };
}

/** Read-only tag queries. Writes are added with bookmark editing/bulk actions. */
export class TagRepository {
  constructor(private readonly database: AppDatabase) {}

  listSummaries(): TagSummary[] {
    const rows = this.database
      .prepare(`
        ${SUMMARY_SELECT}
        GROUP BY tags.id, tags.display_name, tags.name_key
        ORDER BY tags.name_key ASC, tags.id ASC
      `)
      .all() as TagSummaryRow[];
    return rows.map(toSummary);
  }

  findExact(name: string): TagSummary | null {
    const nameKey = normalizeTagName(name).nameKey;
    const row = this.database
      .prepare(`
        ${SUMMARY_SELECT}
        WHERE tags.name_key = ?
        GROUP BY tags.id, tags.display_name, tags.name_key
      `)
      .get(nameKey) as TagSummaryRow | undefined;
    return row ? toSummary(row) : null;
  }

  findPartial(name: string, limit = 20): TagSummary[] {
    const nameKey = normalizeTagName(name).nameKey;
    const safeLimit = Math.max(1, Math.min(Math.trunc(limit), 100));
    const rows = this.database
      .prepare(`
        ${SUMMARY_SELECT}
        WHERE instr(tags.name_key, ?) > 0
        GROUP BY tags.id, tags.display_name, tags.name_key
        ORDER BY tags.name_key ASC, tags.id ASC
        LIMIT ?
      `)
      .all(nameKey, safeLimit) as TagSummaryRow[];
    return rows.map(toSummary);
  }
}
import type {
  Bookmark,
  BookmarkCreate,
  BookmarkPage,
  MetadataStatus,
  Provenance,
} from "../../shared/contracts/api.js";
import type { AppDatabase } from "../db/database.js";

export interface CreateBookmarkValues {
  input: BookmarkCreate;
  address: string;
  normalizedAddress: string;
  fallbackTitle: string;
  now: string;
}

export interface BookmarkIdentity {
  id: number;
  archived: boolean;
}

export interface BookmarkScopeCounts {
  active: number;
  readLater: number;
  archived: number;
}

export interface MetadataUpdate {
  bookmarkId: number;
  addressRevision: number;
  title?: string;
  description?: string;
  iconHash?: string | null;
  status: MetadataStatus;
  errorCode?: string | null;
  fetchedAt: string;
}

interface BookmarkRow {
  id: number;
  address: string;
  normalized_address: string;
  address_revision: number;
  title: string;
  title_sort_key: string;
  title_provenance: Provenance;
  retrieved_title_candidate: string | null;
  description: string;
  description_provenance: Provenance;
  retrieved_description_candidate: string | null;
  icon_hash: string | null;
  metadata_status: MetadataStatus;
  metadata_error_code: string | null;
  metadata_fetched_at: string | null;
  note_markdown: string;
  note_plain: string;
  is_favorite: 0 | 1;
  is_unread: 0 | 1;
  archived_at: string | null;
  created_at: string;
  updated_at: string;
}

export class DuplicateBookmarkError extends Error {
  readonly identity: BookmarkIdentity;

  constructor(identity: BookmarkIdentity) {
    super("That address is already saved.");
    this.name = "DuplicateBookmarkError";
    this.identity = identity;
  }
}

export class BookmarkNotFoundError extends Error {
  constructor() {
    super("Bookmark not found.");
    this.name = "BookmarkNotFoundError";
  }
}

export function titleSortKey(title: string): string {
  return title.normalize("NFKC").toLocaleLowerCase("und");
}

function toBookmark(row: BookmarkRow): Bookmark {
  return {
    id: row.id,
    address: row.address,
    title: row.title,
    titleProvenance: row.title_provenance,
    retrievedTitleCandidate: row.retrieved_title_candidate,
    description: row.description,
    descriptionProvenance: row.description_provenance,
    retrievedDescriptionCandidate: row.retrieved_description_candidate,
    iconUrl: row.icon_hash ? `/api/bookmarks/${row.id}/icon` : null,
    metadataStatus: row.metadata_status,
    metadataErrorCode: row.metadata_error_code,
    noteMarkdown: row.note_markdown,
    tags: [],
    favorite: row.is_favorite === 1,
    unread: row.is_unread === 1,
    archived: row.archived_at !== null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function rowForNormalizedAddress(
  database: AppDatabase,
  normalizedAddress: string,
): BookmarkRow | undefined {
  return database
    .prepare("SELECT * FROM bookmarks WHERE normalized_address = ?")
    .get(normalizedAddress) as BookmarkRow | undefined;
}

export class BookmarkRepository {
  constructor(private readonly database: AppDatabase) {}

  findIdentityByNormalizedAddress(normalizedAddress: string): BookmarkIdentity | null {
    const row = rowForNormalizedAddress(this.database, normalizedAddress);
    return row ? { id: row.id, archived: row.archived_at !== null } : null;
  }

  create(values: CreateBookmarkValues): Bookmark {
    const existing = this.findIdentityByNormalizedAddress(values.normalizedAddress);
    if (existing) throw new DuplicateBookmarkError(existing);

    const titleWasSupplied = values.input.title !== undefined;
    const descriptionWasSupplied = values.input.description !== undefined;
    const title = titleWasSupplied
      ? values.input.title?.trim() || values.fallbackTitle
      : values.fallbackTitle;
    const description = descriptionWasSupplied ? (values.input.description?.trim() ?? "") : "";

    try {
      const result = this.database
        .prepare(`
          INSERT INTO bookmarks (
            address, normalized_address, title, title_sort_key, title_provenance,
            description, description_provenance, metadata_status, note_markdown,
            note_plain, is_favorite, is_unread, created_at, updated_at
          ) VALUES (?, ?, ?, ?, ?, ?, ?, 'pending', ?, '', ?, ?, ?, ?)
        `)
        .run(
          values.address,
          values.normalizedAddress,
          title,
          titleSortKey(title),
          titleWasSupplied ? "user" : "fallback",
          description,
          descriptionWasSupplied ? "user" : "fallback",
          values.input.noteMarkdown ?? "",
          values.input.favorite ? 1 : 0,
          values.input.unread ? 1 : 0,
          values.now,
          values.now,
        );
      return this.get(Number(result.lastInsertRowid));
    } catch (error) {
      const raced = this.findIdentityByNormalizedAddress(values.normalizedAddress);
      if (raced) throw new DuplicateBookmarkError(raced);
      throw error;
    }
  }

  get(id: number): Bookmark {
    const row = this.database.prepare("SELECT * FROM bookmarks WHERE id = ?").get(id) as
      | BookmarkRow
      | undefined;
    if (!row) throw new BookmarkNotFoundError();
    return toBookmark(row);
  }

  getRow(id: number): BookmarkRow | null {
    return (
      (this.database.prepare("SELECT * FROM bookmarks WHERE id = ?").get(id) as
        | BookmarkRow
        | undefined) ?? null
    );
  }

  listActive(limit = 50): BookmarkPage {
    const safeLimit = Math.max(1, Math.min(limit, 100));
    const rows = this.database
      .prepare(
        "SELECT * FROM bookmarks WHERE archived_at IS NULL ORDER BY created_at DESC, id DESC LIMIT ?",
      )
      .all(safeLimit) as BookmarkRow[];
    const total = (
      this.database
        .prepare("SELECT count(*) AS count FROM bookmarks WHERE archived_at IS NULL")
        .get() as { count: number }
    ).count;
    return { items: rows.map(toBookmark), total, nextCursor: null };
  }

  /**
   * Changes only reading state and modification time. The conditional update
   * keeps an idempotent request from pretending the bookmark was modified.
   */
  updateReadingState(id: number, unread: boolean, now: string): Bookmark {
    const update = this.database.transaction(() => {
      const result = this.database
        .prepare(`
          UPDATE bookmarks
          SET is_unread = ?, updated_at = ?
          WHERE id = ? AND is_unread <> ?
        `)
        .run(unread ? 1 : 0, now, id, unread ? 1 : 0);

      if (result.changes === 0 && !this.getRow(id)) throw new BookmarkNotFoundError();
      return this.get(id);
    });
    return update();
  }

  /** Counts navigation scopes in one consistent read. */
  scopeCounts(): BookmarkScopeCounts {
    const row = this.database
      .prepare(`
        SELECT
          count(CASE WHEN archived_at IS NULL THEN 1 END) AS active,
          count(CASE WHEN archived_at IS NULL AND is_unread = 1 THEN 1 END) AS readLater,
          count(CASE WHEN archived_at IS NOT NULL THEN 1 END) AS archived
        FROM bookmarks
      `)
      .get() as BookmarkScopeCounts;
    return row;
  }

  applyMetadata(update: MetadataUpdate): boolean {
    const row = this.getRow(update.bookmarkId);
    if (!row || row.address_revision !== update.addressRevision) return false;

    const title = update.title?.trim();
    const description = update.description?.trim();
    const titleCanApply = Boolean(title) && row.title_provenance !== "user";
    const descriptionCanApply = description !== undefined && row.description_provenance !== "user";

    const result = this.database
      .prepare(`
        UPDATE bookmarks SET
          title = CASE WHEN @titleCanApply THEN @title ELSE title END,
          title_sort_key = CASE WHEN @titleCanApply THEN @titleSortKey ELSE title_sort_key END,
          title_provenance = CASE WHEN @titleCanApply THEN 'retrieved' ELSE title_provenance END,
          retrieved_title_candidate = CASE WHEN @title IS NOT NULL AND title_provenance = 'user' THEN @title ELSE retrieved_title_candidate END,
          description = CASE WHEN @descriptionCanApply THEN @description ELSE description END,
          description_provenance = CASE WHEN @descriptionCanApply THEN 'retrieved' ELSE description_provenance END,
          retrieved_description_candidate = CASE WHEN @description IS NOT NULL AND description_provenance = 'user' THEN @description ELSE retrieved_description_candidate END,
          icon_hash = COALESCE(@iconHash, icon_hash),
          metadata_status = @status,
          metadata_error_code = @errorCode,
          metadata_fetched_at = @fetchedAt,
          updated_at = @fetchedAt
        WHERE id = @bookmarkId AND address_revision = @addressRevision
      `)
      .run({
        bookmarkId: update.bookmarkId,
        addressRevision: update.addressRevision,
        title: title ?? null,
        titleCanApply: titleCanApply ? 1 : 0,
        titleSortKey: title ? titleSortKey(title) : row.title_sort_key,
        description: description ?? null,
        descriptionCanApply: descriptionCanApply ? 1 : 0,
        iconHash: update.iconHash ?? null,
        status: update.status,
        errorCode: update.errorCode ?? null,
        fetchedAt: update.fetchedAt,
      });
    return result.changes === 1;
  }

  pendingMetadata(): Array<{ id: number; address: string; addressRevision: number }> {
    return this.database
      .prepare(
        "SELECT id, address, address_revision AS addressRevision FROM bookmarks WHERE metadata_status = 'pending'",
      )
      .all() as Array<{ id: number; address: string; addressRevision: number }>;
  }
}
import type {
  Bookmark,
  BookmarkPage,
  MetadataStatus,
  Provenance,
  Scope,
  SortOrder,
} from "../../shared/contracts/api.js";
import { parseSearchQueryOrThrow } from "../../shared/search/parser.js";
import type { AppDatabase } from "../db/database.js";
import {
  compileSearchAst,
  normalizeSearchText,
  normalizeTagFilter,
} from "../services/search/search-compiler.js";

export interface SearchRequest {
  scope: Scope;
  query: string;
  tags: readonly string[];
  favorite?: boolean | null;
  unread?: boolean | null;
  sort: SortOrder;
  cursor?: string;
  limit?: number;
}

interface BookmarkRow {
  id: number;
  address: string;
  normalized_address: string;
  address_revision: number;
  title: string;
  title_sort_key: string;
  title_provenance: Provenance;
  retrieved_title_candidate: string | null;
  description: string;
  description_provenance: Provenance;
  retrieved_description_candidate: string | null;
  icon_hash: string | null;
  metadata_status: MetadataStatus;
  metadata_error_code: string | null;
  metadata_fetched_at: string | null;
  note_markdown: string;
  note_plain: string;
  is_favorite: 0 | 1;
  is_unread: 0 | 1;
  archived_at: string | null;
  created_at: string;
  updated_at: string;
}

interface CursorPayload {
  v: 1;
  sort: SortOrder;
  key: string;
  id: number;
}

interface SearchSql {
  withClause: string;
  fromClause: string;
  whereClause: string;
  parameters: unknown[];
}

const SORT_SQL: Record<SortOrder, string> = {
  created_desc: "b.created_at DESC, b.id DESC",
  created_asc: "b.created_at ASC, b.id ASC",
  updated_desc: "b.updated_at DESC, b.id DESC",
  title_asc: "b.title_sort_key ASC, b.id ASC",
};

export class InvalidSearchCursorError extends Error {
  constructor() {
    super("The search cursor is invalid or does not match the current sort.");
    this.name = "InvalidSearchCursorError";
  }
}

function cursorKey(row: BookmarkRow, sort: SortOrder): string {
  if (sort === "created_desc" || sort === "created_asc") return row.created_at;
  if (sort === "updated_desc") return row.updated_at;
  return row.title_sort_key;
}

function encodeCursor(row: BookmarkRow, sort: SortOrder): string {
  const payload: CursorPayload = { v: 1, sort, key: cursorKey(row, sort), id: row.id };
  return Buffer.from(JSON.stringify(payload), "utf8").toString("base64url");
}

function decodeCursor(value: string, sort: SortOrder): CursorPayload {
  try {
    const parsed = JSON.parse(
      Buffer.from(value, "base64url").toString("utf8"),
    ) as Partial<CursorPayload>;
    if (
      parsed.v !== 1 ||
      parsed.sort !== sort ||
      typeof parsed.key !== "string" ||
      parsed.key.length === 0 ||
      !Number.isSafeInteger(parsed.id) ||
      (parsed.id ?? 0) < 1
    ) {
      throw new InvalidSearchCursorError();
    }
    return parsed as CursorPayload;
  } catch (error) {
    if (error instanceof InvalidSearchCursorError) throw error;
    throw new InvalidSearchCursorError();
  }
}

function cursorPredicate(
  sort: SortOrder,
  cursor: CursorPayload,
): { sql: string; values: unknown[] } {
  if (sort === "created_desc") {
    return {
      sql: "(b.created_at < ? OR (b.created_at = ? AND b.id < ?))",
      values: [cursor.key, cursor.key, cursor.id],
    };
  }
  if (sort === "created_asc") {
    return {
      sql: "(b.created_at > ? OR (b.created_at = ? AND b.id > ?))",
      values: [cursor.key, cursor.key, cursor.id],
    };
  }
  if (sort === "updated_desc") {
    return {
      sql: "(b.updated_at < ? OR (b.updated_at = ? AND b.id < ?))",
      values: [cursor.key, cursor.key, cursor.id],
    };
  }
  return {
    sql: "(b.title_sort_key > ? OR (b.title_sort_key = ? AND b.id > ?))",
    values: [cursor.key, cursor.key, cursor.id],
  };
}

function scopePredicate(scope: Scope): string {
  if (scope === "read_later") return "b.archived_at IS NULL AND b.is_unread = 1";
  if (scope === "archived") return "b.archived_at IS NOT NULL";
  return "b.archived_at IS NULL";
}

function toBookmark(row: BookmarkRow, tags: Bookmark["tags"]): Bookmark {
  return {
    id: row.id,
    address: row.address,
    title: row.title,
    titleProvenance: row.title_provenance,
    retrievedTitleCandidate: row.retrieved_title_candidate,
    description: row.description,
    descriptionProvenance: row.description_provenance,
    retrievedDescriptionCandidate: row.retrieved_description_candidate,
    iconUrl: row.icon_hash ? `/api/bookmarks/${row.id}/icon` : null,
    metadataStatus: row.metadata_status,
    metadataErrorCode: row.metadata_error_code,
    noteMarkdown: row.note_markdown,
    tags,
    favorite: row.is_favorite === 1,
    unread: row.is_unread === 1,
    archived: row.archived_at !== null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export class SearchRepository {
  constructor(private readonly database: AppDatabase) {
    this.database.function("search_normalize", { deterministic: true }, (value: unknown) =>
      normalizeSearchText(typeof value === "string" ? value : ""),
    );
    this.verifySearchSupport();
  }

  /** Fail clearly during startup if the migration/index is absent or unusable. */
  verifySearchSupport(): void {
    try {
      this.database
        .prepare("SELECT rowid FROM bookmark_search WHERE bookmark_search MATCH ? LIMIT 0")
        .all('"trigram capability probe"');
    } catch (error) {
      throw new Error(
        `SQLite FTS5 trigram search is unavailable: ${error instanceof Error ? error.message : "unknown error"}`,
        { cause: error },
      );
    }
  }

  search(criteria: SearchRequest): BookmarkPage {
    const limit = Math.max(1, Math.min(criteria.limit ?? 50, 100));
    const base = this.buildSql(criteria);
    const total = (
      this.database
        .prepare(
          `${base.withClause} SELECT count(*) AS count ${base.fromClause} ${base.whereClause}`,
        )
        .get(...base.parameters) as { count: number }
    ).count;

    const pageWhere: string[] = [];
    const pageParameters = [...base.parameters];
    if (criteria.cursor) {
      const predicate = cursorPredicate(
        criteria.sort,
        decodeCursor(criteria.cursor, criteria.sort),
      );
      pageWhere.push(predicate.sql);
      pageParameters.push(...predicate.values);
    }
    const cursorSql = pageWhere.length > 0 ? ` AND ${pageWhere.join(" AND ")}` : "";
    const fetched = this.database
      .prepare(
        `${base.withClause} SELECT b.* ${base.fromClause} ${base.whereClause}${cursorSql} ` +
          `ORDER BY ${SORT_SQL[criteria.sort]} LIMIT ?`,
      )
      .all(...pageParameters, limit + 1) as BookmarkRow[];

    const hasMore = fetched.length > limit;
    const rows = hasMore ? fetched.slice(0, limit) : fetched;
    const tagsByBookmark = this.tagsFor(rows.map(({ id }) => id));
    const items = rows.map((row) => toBookmark(row, tagsByBookmark.get(row.id) ?? []));

    return {
      items,
      total,
      nextCursor:
        hasMore && rows.length > 0
          ? encodeCursor(rows[rows.length - 1] as BookmarkRow, criteria.sort)
          : null,
    };
  }

  /** Full current result membership, used later to create stable bulk snapshots. */
  matchingIds(criteria: Omit<SearchRequest, "cursor" | "limit">): number[] {
    const base = this.buildSql(criteria);
    return (
      this.database
        .prepare(
          `${base.withClause} SELECT b.id ${base.fromClause} ${base.whereClause} ` +
            `ORDER BY ${SORT_SQL[criteria.sort]}`,
        )
        .all(...base.parameters) as Array<{ id: number }>
    ).map(({ id }) => id);
  }

  /** Replace one contentful FTS row with application-normalized field values. */
  synchronizeBookmark(bookmarkId: number): void {
    const row = this.database
      .prepare("SELECT id, title, address, description, note_plain FROM bookmarks WHERE id = ?")
      .get(bookmarkId) as
      | { id: number; title: string; address: string; description: string; note_plain: string }
      | undefined;
    if (!row) {
      this.database.prepare("DELETE FROM bookmark_search WHERE rowid = ?").run(bookmarkId);
      return;
    }

    const replace = this.database.transaction(() => {
      this.database.prepare("DELETE FROM bookmark_search WHERE rowid = ?").run(bookmarkId);
      this.database
        .prepare(
          "INSERT INTO bookmark_search(rowid, title, address, description, note_plain) VALUES (?, ?, ?, ?, ?)",
        )
        .run(
          row.id,
          normalizeSearchText(row.title),
          normalizeSearchText(row.address),
          normalizeSearchText(row.description),
          normalizeSearchText(row.note_plain),
        );
    });
    replace();
  }

  rebuildSearchIndex(): void {
    const ids = this.database.prepare("SELECT id FROM bookmarks ORDER BY id").all() as Array<{
      id: number;
    }>;
    const rebuild = this.database.transaction(() => {
      this.database.prepare("DELETE FROM bookmark_search").run();
      for (const { id } of ids) this.synchronizeBookmark(id);
    });
    rebuild();
  }

  private buildSql(criteria: Omit<SearchRequest, "cursor" | "limit">): SearchSql {
    const compiled = compileSearchAst(parseSearchQueryOrThrow(criteria.query));
    const withClause = `WITH search_matches(id) AS (${compiled.sql})`;
    const fromClause = "FROM bookmarks b JOIN search_matches m ON m.id = b.id";
    const predicates = [scopePredicate(criteria.scope)];
    const parameters: unknown[] = [...compiled.parameters];

    if (criteria.favorite !== null && criteria.favorite !== undefined) {
      predicates.push("b.is_favorite = ?");
      parameters.push(criteria.favorite ? 1 : 0);
    }
    if (criteria.unread !== null && criteria.unread !== undefined) {
      predicates.push("b.is_unread = ?");
      parameters.push(criteria.unread ? 1 : 0);
    }

    const tagKeys = [...new Set(criteria.tags.map(normalizeTagFilter))];
    if (tagKeys.length > 0) {
      predicates.push(`b.id IN (
        SELECT bt.bookmark_id
        FROM bookmark_tags bt
        JOIN tags t ON t.id = bt.tag_id
        WHERE t.name_key IN (${tagKeys.map(() => "?").join(", ")})
        GROUP BY bt.bookmark_id
        HAVING count(DISTINCT t.name_key) = ?
      )`);
      parameters.push(...tagKeys, tagKeys.length);
    }

    return {
      withClause,
      fromClause,
      whereClause: `WHERE ${predicates.join(" AND ")}`,
      parameters,
    };
  }

  private tagsFor(bookmarkIds: number[]): Map<number, Bookmark["tags"]> {
    const grouped = new Map<number, Bookmark["tags"]>();
    if (bookmarkIds.length === 0) return grouped;
