        ? "VALIDATION_ERROR"
        : statusCode >= 500
          ? "INTERNAL_ERROR"
          : "REQUEST_ERROR",
      message:
        statusCode >= 500
          ? "The request could not be completed."
          : validation
            ? "One or more request fields are invalid."
            : error.message,
    });
  });

