import type { ListItem, PhrasingContent, RootContent } from "mdast";
import { fromMarkdown } from "mdast-util-from-markdown";
import { toString } from "mdast-util-to-string";

import {
  isSafeNoteLinkUrl,
  NoteValidationError,
  type PreparedNote,
  type SafeNoteNode,
  type SafeNoteRoot,
} from "../../../shared/types/notes.js";

/** Keep editable source stable across operating systems without altering hard breaks. */
export function canonicalizeNoteMarkdown(markdown: string): string {
  return markdown.replace(/^\uFEFF/u, "").replace(/\r\n?/gu, "\n");
}

function childrenOf(nodes: readonly PhrasingContent[]): SafeNoteNode[] {
  return nodes.flatMap((node) => {
    const safe = safePhrasing(node);
    return safe ? [safe] : [];
  });
}

function safePhrasing(node: PhrasingContent): SafeNoteNode | null {
  switch (node.type) {
    case "text":
      return {
        type: "text",
        value: toString(node, { includeHtml: false, includeImageAlt: false }),
      };
    case "inlineCode":
      return {
        type: "inlineCode",
        value: toString(node, { includeHtml: false, includeImageAlt: false }),
      };
    case "break":
      return { type: "break" };
    case "strong":
      return { type: "strong", children: childrenOf(node.children) };
    case "emphasis":
      return { type: "emphasis", children: childrenOf(node.children) };
    case "link": {
      if (!isSafeNoteLinkUrl(node.url)) throw new NoteValidationError(node.url);
      return {
        type: "link",
        url: node.url,
        title: node.title ?? null,
        children: childrenOf(node.children),
      };
    }
    default:
      return null;
  }
}

function safeListItem(node: ListItem): SafeNoteNode {
  return {
    type: "listItem",
    children: node.children.flatMap((child) => {
      const safe = safeBlock(child);
      return safe ? [safe] : [];
    }),
  };
}

function safeBlock(node: RootContent): SafeNoteNode | null {
  switch (node.type) {
    case "heading":
      return { type: "heading", depth: node.depth, children: childrenOf(node.children) };
    case "paragraph":
      return { type: "paragraph", children: childrenOf(node.children) };
    case "list":
      return {
        type: "list",
        ordered: node.ordered === true,
        start: node.start ?? null,
        children: node.children.map(safeListItem),
      };
    default:
      return null;
  }
}

export function parseSafeNoteAst(markdown: string): SafeNoteRoot {
  const parsed = fromMarkdown(markdown);
  return {
    type: "root",
    children: parsed.children.flatMap((child) => {
      const safe = safeBlock(child);
      return safe ? [safe] : [];
    }),
  };
}

function textForNode(node: SafeNoteNode): string {
  switch (node.type) {
    case "text":
    case "inlineCode":
      return node.value;
    case "break":
      return "\n";
    case "strong":
    case "emphasis":
    case "link":
    case "heading":
    case "paragraph":
      return node.children.map(textForNode).join("");
    case "root":
    case "list":
    case "listItem":
      return node.children.map(textForNode).join("\n");
  }
}

/** Derives only text the approved renderer can visibly display. */
export function extractNotePlainText(ast: SafeNoteRoot): string {
  return textForNode(ast)
    .split("\n")
    .map((line) => line.replace(/\s+/gu, " ").trim())
    .filter(Boolean)
    .join("\n");
}

export function prepareNote(markdown: string): PreparedNote {
  const canonical = canonicalizeNoteMarkdown(markdown);
  const ast = parseSafeNoteAst(canonical);
  return { markdown: canonical, plainText: extractNotePlainText(ast), ast };
}
import { type Static, type TSchema, Type } from "typebox";

import { ScopeSchema } from "./api.js";

function inline<T extends TSchema>(schema: T): T {
  const copy = { ...schema } as T & { $id?: string };
  delete copy.$id;
  return copy;
}

/** Base error payload used by validation, not-found, and selection errors. */
export const ProblemSchema = Type.Object(
  {
    code: Type.String(),
    message: Type.String(),
    field: Type.Optional(Type.String()),
  },
  { $id: "Problem" },
);
export type Problem = Static<typeof ProblemSchema>;

/** Position-aware error returned for invalid search syntax or criteria. */
export const SearchProblemSchema = Type.Object(
  {
    code: Type.String(),
    message: Type.String(),
    field: Type.Optional(Type.String()),
    start: Type.Integer({ minimum: 0 }),
    end: Type.Integer({ minimum: 0 }),
    hint: Type.String(),
  },
  { $id: "SearchProblem" },
);
export type SearchProblem = Static<typeof SearchProblemSchema>;

/** Conflict payload that directs the client to the existing bookmark editor. */
export const DuplicateBookmarkProblemSchema = Type.Object(
  {
    code: Type.Literal("DUPLICATE_BOOKMARK"),
    message: Type.String(),
    field: Type.Optional(Type.String()),
    existingBookmarkId: Type.Integer(),
    existingScope: Type.Optional(inline(ScopeSchema)),
  },
  { $id: "DuplicateBookmarkProblem" },
);
export type DuplicateBookmarkProblem = Static<typeof DuplicateBookmarkProblemSchema>;

/** Conflict payload returned for a normalized duplicate saved-view name. */
export const DuplicateSavedViewProblemSchema = Type.Object(
  {
    code: Type.Literal("DUPLICATE_SAVED_VIEW_NAME"),
    message: Type.String(),
    field: Type.Optional(Type.Literal("name")),
  },
  { $id: "DuplicateSavedViewProblem" },
);
export type DuplicateSavedViewProblem = Static<typeof DuplicateSavedViewProblemSchema>;

export const errorSchemas = [
  ProblemSchema,
  SearchProblemSchema,
  DuplicateBookmarkProblemSchema,
  DuplicateSavedViewProblemSchema,
] as const;
export const ADDRESS_ERROR_CODES = {
  required: "ADDRESS_REQUIRED",
  invalid: "ADDRESS_INVALID",
  unsupportedScheme: "ADDRESS_UNSUPPORTED_SCHEME",
} as const;

export type AddressValidationErrorCode =
  (typeof ADDRESS_ERROR_CODES)[keyof typeof ADDRESS_ERROR_CODES];

/** A field-specific failure safe to map to an API problem or inline form guidance. */
export class AddressValidationError extends Error {
  readonly field = "address" as const;

  constructor(
    readonly code: AddressValidationErrorCode,
    message: string,
  ) {
    super(message);
    this.name = "AddressValidationError";
  }
}

export interface NormalizedAddress {
  /** The user's destination with surrounding whitespace removed. */
  address: string;
  /** The exact key used by the database uniqueness constraint. */
  normalizedAddress: string;
  /** The successfully parsed WHATWG URL. */
  url: URL;
}

const SCHEME_PATTERN = /^([A-Za-z][A-Za-z\d+.-]*):/u;
const EXPLICIT_AUTHORITY_PATTERN = /^([A-Za-z][A-Za-z\d+.-]*):\/\/([^/?#]*)(.*)$/su;

function containsAsciiControl(value: string): boolean {
  for (let index = 0; index < value.length; index += 1) {
    const code = value.charCodeAt(index);
    if (code <= 31 || code === 127) return true;
  }
  return false;
}

function invalidAddress(
  message = "Enter a complete web address, such as https://example.com.",
): never {
  throw new AddressValidationError(ADDRESS_ERROR_CODES.invalid, message);
}

function rawPortFromAuthority(authority: string): string | undefined {
  const hostAndPort = authority.slice(authority.lastIndexOf("@") + 1);

  if (hostAndPort.startsWith("[")) {
    const closingBracket = hostAndPort.indexOf("]");
    if (closingBracket === -1) {
      return invalidAddress();
    }

    const remainder = hostAndPort.slice(closingBracket + 1);
    if (remainder === "") return undefined;
    if (!remainder.startsWith(":")) return invalidAddress();
    return remainder.slice(1);
  }

  const colon = hostAndPort.lastIndexOf(":");
  return colon === -1 ? undefined : hostAndPort.slice(colon + 1);
}

/**
 * Validates a bookmark destination with the WHATWG parser and derives the
 * deliberately narrow FR-005 identity. Path, query and fragment source text
 * stays distinct; only scheme/host case, default ports, and the root path are
 * normalized.
 */
export function normalizeAddress(input: string): NormalizedAddress {
  const address = input.trim();
  if (address === "") {
    throw new AddressValidationError(ADDRESS_ERROR_CODES.required, "Enter a web address to save.");
  }

  const schemeMatch = SCHEME_PATTERN.exec(address);
  if (schemeMatch && !/^https?$/iu.test(schemeMatch[1] ?? "")) {
    throw new AddressValidationError(
      ADDRESS_ERROR_CODES.unsupportedScheme,
      "Use an address beginning with http:// or https://.",
    );
  }

  const sourceMatch = EXPLICIT_AUTHORITY_PATTERN.exec(address);
  if (!sourceMatch || containsAsciiControl(address)) return invalidAddress();

  const [, rawScheme = "", rawAuthority = "", rawSuffix = ""] = sourceMatch;
  if (!/^https?$/iu.test(rawScheme) || rawAuthority === "") return invalidAddress();

  // For special URLs WHATWG treats backslashes as slashes. Reject that
  // surprising spelling outside query/fragment instead of silently changing
  // its destination or duplicate identity.
  const beforeQueryOrFragment = address.split(/[?#]/u, 1)[0] ?? address;
  if (beforeQueryOrFragment.includes("\\")) return invalidAddress();

  const rawPort = rawPortFromAuthority(rawAuthority);
  if (rawPort !== undefined && !/^\d+$/u.test(rawPort)) return invalidAddress();

  let url: URL;
  try {
    url = new URL(address);
  } catch {
    return invalidAddress();
  }

  if ((url.protocol !== "http:" && url.protocol !== "https:") || url.hostname === "") {
    return invalidAddress();
  }

  const at = rawAuthority.lastIndexOf("@");
  const credentials = at === -1 ? "" : rawAuthority.slice(0, at + 1);
  const port = url.port === "" ? "" : `:${url.port}`;
  const suffix = rawSuffix === "" ? "/" : /^[?#]/u.test(rawSuffix) ? `/${rawSuffix}` : rawSuffix;
  const normalizedAddress = `${url.protocol}//${credentials}${url.hostname.toLowerCase()}${port}${suffix}`;

  return { address, normalizedAddress, url };
}

export function addressesHaveSameIdentity(left: string, right: string): boolean {
  return normalizeAddress(left).normalizedAddress === normalizeAddress(right).normalizedAddress;
}
