export interface ClockAdvance {
  milliseconds?: number;
  seconds?: number;
  minutes?: number;
  hours?: number;
  days?: number;
}

function toMilliseconds(advance: number | ClockAdvance): number {
  if (typeof advance === "number") return advance;

  return (
    (advance.milliseconds ?? 0) +
    (advance.seconds ?? 0) * 1_000 +
    (advance.minutes ?? 0) * 60_000 +
    (advance.hours ?? 0) * 3_600_000 +
    (advance.days ?? 0) * 86_400_000
  );
}

function parseTime(value: string | number | Date): number {
  const milliseconds = value instanceof Date ? value.getTime() : new Date(value).getTime();
  if (!Number.isFinite(milliseconds)) {
    throw new TypeError(`Invalid test clock value: ${String(value)}`);
  }
  return milliseconds;
}

/** A mutable clock whose returned Dates cannot mutate its internal state. */
export class TestClock {
  #milliseconds: number;

  constructor(initialTime: string | number | Date = DEFAULT_TEST_TIME) {
    this.#milliseconds = parseTime(initialTime);
  }

  readonly now = (): Date => new Date(this.#milliseconds);

  iso(): string {
    return this.now().toISOString();
  }

  set(value: string | number | Date): Date {
    this.#milliseconds = parseTime(value);
    return this.now();
  }

  advance(by: number | ClockAdvance): Date {
    const milliseconds = toMilliseconds(by);
    if (!Number.isFinite(milliseconds)) {
      throw new TypeError("Test clock advance must be finite");
    }
    this.#milliseconds += milliseconds;
    return this.now();
  }
}

export function createTestClock(
  initialTime: string | number | Date = DEFAULT_TEST_TIME,
): TestClock {
  return new TestClock(initialTime);
}

export function fixedNow(value: string | number | Date = DEFAULT_TEST_TIME): () => Date {
  const milliseconds = parseTime(value);
  return () => new Date(milliseconds);
}
import type { FastifyInstance, FastifyReply } from "fastify";
import {
  type MetadataPreview,
  type MetadataPreviewRequest,
  MetadataPreviewRequestSchema,
} from "../../shared/contracts/api.js";
import { AddressValidationError } from "../../shared/types/address.js";
import { BookmarkRepository } from "../repositories/bookmark-repository.js";
import {
  fallbackTitleFromAddress,
  normalizeAddress,
} from "../services/bookmarks/address-normalizer.js";

export interface MetadataPreviewer {
  preview(address: string): Promise<MetadataPreview>;
}

function fallbackPreview(address: string): MetadataPreview {
  const title = fallbackTitleFromAddress(address);
  return {
    address,
    status: "pending",
    fallbackTitle: title,
    title,
    description: "",
    iconAvailable: false,
    errorCode: null,
  };
}

function addressProblem(reply: FastifyReply, error: AddressValidationError) {
  return reply.code(422).send({ code: error.code, message: error.message, field: error.field });
}

export async function registerMetadataRoutes(app: FastifyInstance, previewer?: MetadataPreviewer) {
  const bookmarks = new BookmarkRepository(app.database);

  app.post<{ Body: MetadataPreviewRequest }>(
    "/api/metadata/preview",
    { schema: { body: MetadataPreviewRequestSchema } },
    async (request, reply) => {
      try {
        const normalized = normalizeAddress(request.body.address);
        const existing = bookmarks.findIdentityByNormalizedAddress(normalized.normalizedAddress);
        if (existing) {
          return reply.code(409).send({
            code: "DUPLICATE_BOOKMARK",
            message: "That address is already saved. Open the existing bookmark to edit it.",
            field: "address",
            existingBookmarkId: existing.id,
            existingScope: existing.archived ? "archived" : "active",
          });
        }
        return previewer?.preview(normalized.address) ?? fallbackPreview(normalized.address);
      } catch (error) {
        if (error instanceof AddressValidationError) return addressProblem(reply, error);
        throw error;
      }
    },
  );
}
