    let isRestored = false;
    vi.spyOn(api, "getHealth").mockResolvedValue({ status: "ready" });
    vi.spyOn(api, "listTags").mockResolvedValue([]);
    vi.spyOn(api, "listBookmarks").mockImplementation(async (query = {}) => {
