        ...bookmark,
        ...patch,
        tags: (patch.tags ?? []).map((name, index) => ({ id: index + 10, name })),
      }));
    const onSaved = vi.fn();
    const user = userEvent.setup();
    render(
      <BookmarkEditor
        bookmark={bookmark}
