        address,
        title,
        title.toLowerCase(),
        phrase,
        id % 17 === 0 ? "ui notes" : "long form notes",
        id % 2,
        id % 3 === 0 ? 1 : 0,
        id % 19 === 0 ? CREATED : null,
        createdAt,
