      );
      if (id % 5 === 0) attachTag.run(id, "research");
      if (id % 13 === 0) attachTag.run(id, "machine learning");
    }
  })();
}

function percentile95(samples: number[]): number {
  const sorted = [...samples].sort((left, right) => left - right);
  return sorted[Math.ceil(sorted.length * 0.95) - 1] ?? Number.POSITIVE_INFINITY;
}

describe("10,000 bookmark search performance", () => {
  it("returns total count and first page under the one-second p95 target", async () => {
    await withTestDatabase(({ database }) => {
      seedTenThousand(database);
      const repository = new SearchRepository(database);
      const operations: SearchRequest[] = [
        criteria({ query: "quasarneedle" }),
        criteria({ query: "common" }),
        criteria({ query: "ui" }),
        criteria({ query: '"distributed systems"' }),
        criteria({ query: "common material notes example library" }),
        criteria({ query: "#research", tags: ["machine learning"] }),
        criteria({ tags: ["research"], favorite: true, sort: "created_asc" }),
        criteria({ unread: true, sort: "updated_desc" }),
        criteria({ sort: "title_asc" }),
      ];

      const timings: number[] = [];
      for (let iteration = 0; iteration < 3; iteration += 1) {
        for (const operation of operations) {
          const started = performance.now();
          const page = repository.search(operation);
          timings.push(performance.now() - started);
          expect(page.items.length).toBeLessThanOrEqual(50);
          expect(page.total).toBeGreaterThanOrEqual(page.items.length);
        }
      }

      const rare = repository.search(criteria({ query: "quasarneedle" }));
      expect(rare.total).toBe(1);
      expect(rare.items[0]?.id).toBe(7);
      expect(percentile95(timings)).toBeLessThan(1_000);
    });
  }, 30_000);
});
