function seedTenThousand(database: AppDatabase): void {
  const insertBookmark = database.prepare(`
    INSERT INTO bookmarks (
      id, address, normalized_address, title, title_sort_key, title_provenance,
      description, description_provenance, metadata_status, note_markdown, note_plain,
      is_favorite, is_unread, archived_at, created_at, updated_at
    ) VALUES (?, ?, ?, ?, ?, 'retrieved', ?, 'retrieved', 'complete', '', ?, ?, ?, ?, ?, ?)
  `);
  const insertTag = database.prepare(
    "INSERT OR IGNORE INTO tags(display_name, name_key, created_at) VALUES (?, ?, ?)",
  );
  const attachTag = database.prepare(`
    INSERT INTO bookmark_tags(bookmark_id, tag_id)
    SELECT ?, id FROM tags WHERE name_key = ?
  `);

  database.transaction(() => {
    insertTag.run("Research", "research", CREATED);
    insertTag.run("Machine Learning", "machine learning", CREATED);
    for (let id = 1; id <= 10_000; id += 1) {
      const rare = id === 7 ? "quasarneedle" : "";
      const phrase = id % 211 === 0 ? "distributed systems" : "reference material";
      const title = `Bookmark ${String(id).padStart(5, "0")} common ${rare}`;
      const address = `https://example.test/library/${id}`;
      const createdAt = new Date(Date.parse(CREATED) - id * 1000).toISOString();
      insertBookmark.run(
        id,
        address,
        address,
        title,
        title.toLowerCase(),
        phrase,
        id % 17 === 0 ? "ui notes" : "long form notes",
        id % 2,
        id % 3 === 0 ? 1 : 0,
        id % 19 === 0 ? CREATED : null,
        createdAt,
        createdAt,
      );
      if (id % 5 === 0) attachTag.run(id, "research");
      if (id % 13 === 0) attachTag.run(id, "machine learning");
    }
  })();
}

function percentile95(samples: number[]): number {
  const sorted = [...samples].sort((left, right) => left - right);
  return sorted[Math.ceil(sorted.length * 0.95) - 1] ?? Number.POSITIVE_INFINITY;
}

describe("10,000 bookmark search performance", () => {
  it("returns total count and first page under the one-second p95 target", async () => {
    await withTestDatabase(({ database }) => {
      seedTenThousand(database);
      const repository = new SearchRepository(database);
      const operations: SearchRequest[] = [
        criteria({ query: "quasarneedle" }),
        criteria({ query: "common" }),
        criteria({ query: "ui" }),
        criteria({ query: '"distributed systems"' }),
        criteria({ query: "common material notes example library" }),
        criteria({ query: "#research", tags: ["machine learning"] }),
        criteria({ tags: ["research"], favorite: true, sort: "created_asc" }),
        criteria({ unread: true, sort: "updated_desc" }),
        criteria({ sort: "title_asc" }),
      ];

      const timings: number[] = [];
      for (let iteration = 0; iteration < 3; iteration += 1) {
        for (const operation of operations) {
          const started = performance.now();
          const page = repository.search(operation);
          timings.push(performance.now() - started);
          expect(page.items.length).toBeLessThanOrEqual(50);
          expect(page.total).toBeGreaterThanOrEqual(page.items.length);
        }
      }

      const rare = repository.search(criteria({ query: "quasarneedle" }));
      expect(rare.total).toBe(1);
      expect(rare.items[0]?.id).toBe(7);
      expect(percentile95(timings)).toBeLessThan(1_000);
    });
  }, 30_000);
});
import type { BulkAction, BulkResult } from "../../../shared/contracts/api.js";
import type { AppDatabase } from "../../db/database.js";
import {
  SelectionRepository,
  type SelectionRepositoryOptions,
} from "../../repositories/selection-repository.js";
import { normalizeTagName } from "../../repositories/tag-repository.js";
import { BookmarkDeleteService } from "../bookmarks/bookmark-delete-service.js";

function placeholders(count: number): string {
  return Array.from({ length: count }, () => "?").join(", ");
}

export class BulkActionService {
  private readonly selections: SelectionRepository;
  private readonly deletion: BookmarkDeleteService;

  constructor(
    private readonly database: AppDatabase,
    private readonly now: () => Date = () => new Date(),
    selectionOptions: SelectionRepositoryOptions = {},
  ) {
    this.selections = new SelectionRepository(database, now, selectionOptions);
    this.deletion = new BookmarkDeleteService(database);
  }

  apply(selectionId: string, action: BulkAction): BulkResult {
    return this.selections.consume(selectionId, (selection) => {
      const processedCount = selection.bookmarkIds.length;
      if (processedCount === 0) {
        return { selectedCount: selection.selectedCount, processedCount: 0, changedCount: 0 };
      }

      const changedCount =
        action.type === "add_tags" || action.type === "remove_tags"
          ? this.applyTags(selection.bookmarkIds, action.type, action.tags)
          : this.applyState(selection.bookmarkIds, action.type);
      return { selectedCount: selection.selectedCount, processedCount, changedCount };
    });
  }

  private applyTags(
    bookmarkIds: readonly number[],
    type: "add_tags" | "remove_tags",
    names: readonly string[],
  ): number {
    const normalized = new Map<string, { displayName: string; nameKey: string }>();
    for (const name of names) {
      const tag = normalizeTagName(name);
      if (!normalized.has(tag.nameKey)) normalized.set(tag.nameKey, tag);
    }
    const tags = [...normalized.values()];
    const keys = tags.map(({ nameKey }) => nameKey);
    const now = this.now().toISOString();
    const bookmarkSlots = placeholders(bookmarkIds.length);
    const tagSlots = placeholders(keys.length);

    if (type === "add_tags") {
      const insertTag = this.database.prepare(`
        INSERT INTO tags(display_name, name_key, created_at)
        VALUES (?, ?, ?)
        ON CONFLICT(name_key) DO NOTHING
      `);
      for (const tag of tags) insertTag.run(tag.displayName, tag.nameKey, now);

      const changedIds = (
        this.database
          .prepare(`
            SELECT b.id
            FROM bookmarks b
            WHERE b.id IN (${bookmarkSlots})
              AND EXISTS (
                SELECT 1 FROM tags t
                WHERE t.name_key IN (${tagSlots})
                  AND NOT EXISTS (
                    SELECT 1 FROM bookmark_tags bt
                    WHERE bt.bookmark_id = b.id AND bt.tag_id = t.id
                  )
              )
            ORDER BY b.id
          `)
          .all(...bookmarkIds, ...keys) as Array<{ id: number }>
      ).map(({ id }) => id);

      const attach = this.database.prepare(`
        INSERT OR IGNORE INTO bookmark_tags(bookmark_id, tag_id)
        SELECT b.id, t.id
        FROM bookmarks b, tags t
        WHERE b.id IN (${bookmarkSlots}) AND t.name_key = ?
      `);
      for (const key of keys) attach.run(...bookmarkIds, key);
      this.touch(changedIds, now);
      return changedIds.length;
    }

    const changedIds = (
      this.database
        .prepare(`
          SELECT DISTINCT bt.bookmark_id AS id
          FROM bookmark_tags bt
          JOIN tags t ON t.id = bt.tag_id
          WHERE bt.bookmark_id IN (${bookmarkSlots})
            AND t.name_key IN (${tagSlots})
          ORDER BY bt.bookmark_id
        `)
        .all(...bookmarkIds, ...keys) as Array<{ id: number }>
    ).map(({ id }) => id);
    this.database
      .prepare(`
        DELETE FROM bookmark_tags
        WHERE bookmark_id IN (${bookmarkSlots})
          AND tag_id IN (SELECT id FROM tags WHERE name_key IN (${tagSlots}))
      `)
      .run(...bookmarkIds, ...keys);
    this.cleanupOrphanTags();
    this.touch(changedIds, now);
    return changedIds.length;
  }

  private applyState(
    bookmarkIds: readonly number[],
    type: Exclude<BulkAction["type"], "add_tags" | "remove_tags">,
  ): number {
    const slots = placeholders(bookmarkIds.length);
    const now = this.now().toISOString();
    if (type === "delete") {
      return this.deletion.deleteMany(bookmarkIds);
    }

    const assignments = {
      favorite: { set: "is_favorite = 1", condition: "is_favorite = 0" },
      unfavorite: { set: "is_favorite = 0", condition: "is_favorite = 1" },
      mark_unread: { set: "is_unread = 1", condition: "is_unread = 0" },
      mark_read: { set: "is_unread = 0", condition: "is_unread = 1" },
      archive: { set: "archived_at = ?", condition: "archived_at IS NULL", value: now },
      restore: { set: "archived_at = NULL", condition: "archived_at IS NOT NULL" },
    } as const;
    const assignment = assignments[type];
    const parameters =
      "value" in assignment ? [assignment.value, now, ...bookmarkIds] : [now, ...bookmarkIds];
    const result = this.database
      .prepare(`
        UPDATE bookmarks
        SET ${assignment.set}, updated_at = ?
        WHERE id IN (${slots}) AND ${assignment.condition}
      `)
      .run(...parameters);
    return result.changes;
  }

  private touch(bookmarkIds: readonly number[], now: string): void {
    if (bookmarkIds.length === 0) return;
    this.database
      .prepare(
        `UPDATE bookmarks SET updated_at = ? WHERE id IN (${placeholders(bookmarkIds.length)})`,
      )
      .run(now, ...bookmarkIds);
  }

  private cleanupOrphanTags(): void {
    this.database.exec(`
      DELETE FROM tags
      WHERE NOT EXISTS (
        SELECT 1 FROM bookmark_tags WHERE bookmark_tags.tag_id = tags.id
      )
    `);
  }
}
import { createHash, randomBytes } from "node:crypto";
import type { SearchCriteria, Selection } from "../../shared/contracts/api.js";
import { normalizeExactTag } from "../../shared/search/tokenizer.js";
import type { AppDatabase } from "../db/database.js";
import { SearchRepository } from "./search-repository.js";

const DEFAULT_SELECTION_TTL_MS = 15 * 60 * 1_000;
const HASH_PATTERN = /^sha256:[a-f0-9]{64}$/u;

interface SelectionRow {
  id: string;
  criteria_hash: string;
  selected_count: number;
  created_at: string;
  expires_at: string;
}

export interface SelectionRepositoryOptions {
  ttlMs?: number;
  token?: () => string;
}

export interface ConsumedSelection {
  id: string;
  criteriaHash: string;
  selectedCount: number;
  bookmarkIds: readonly number[];
}

export class SelectionNotFoundError extends Error {
  constructor() {
    super("Selection not found or already consumed.");
    this.name = "SelectionNotFoundError";
  }
}

export class SelectionExpiredError extends Error {
  constructor() {
    super("The selection expired. Select the bookmarks again.");
    this.name = "SelectionExpiredError";
  }
}

export class SelectionCriteriaHashError extends Error {
  readonly code = "SELECTION_CRITERIA_MISMATCH";
  readonly field = "criteriaHash";

  constructor() {
    super("The selection does not match the supplied view criteria.");
    this.name = "SelectionCriteriaHashError";
  }
}

export class EmptySelectionError extends Error {
  readonly code = "EMPTY_SELECTION";
  readonly field = "ids";

  constructor() {
    super("Select at least one existing bookmark.");
    this.name = "EmptySelectionError";
  }
}

function canonicalCriteria(criteria: SearchCriteria) {
  return {
    scope: criteria.scope,
    query: criteria.query,
    tags: [...new Set(criteria.tags.map(normalizeExactTag))].sort(),
    favorite: criteria.favorite ?? null,
    unread: criteria.unread ?? null,
    sort: criteria.sort,
  };
}

export function computeCriteriaHash(criteria: SearchCriteria): string {
  const digest = createHash("sha256")
    .update(JSON.stringify(canonicalCriteria(criteria)), "utf8")
    .digest("hex");
  return `sha256:${digest}`;
}

function toSelection(row: SelectionRow): Selection {
  return {
    id: row.id,
    criteriaHash: row.criteria_hash,
    selectedCount: row.selected_count,
    expiresAt: row.expires_at,
  };
}

function isExpired(row: SelectionRow, now: string): boolean {
  return row.expires_at <= now;
}

export class SelectionRepository {
  private readonly search: SearchRepository;
  private readonly ttlMs: number;
  private readonly token: () => string;

  constructor(
    private readonly database: AppDatabase,
    private readonly now: () => Date = () => new Date(),
    options: SelectionRepositoryOptions = {},
  ) {
    this.search = new SearchRepository(database);
    this.ttlMs = options.ttlMs ?? DEFAULT_SELECTION_TTL_MS;
    this.token = options.token ?? (() => randomBytes(24).toString("base64url"));
    if (!Number.isFinite(this.ttlMs) || this.ttlMs <= 0) {
      throw new RangeError("Selection expiry must be a positive duration.");
    }
    this.cleanupExpired();
  }

  createIds(ids: readonly number[], criteriaHash: string): Selection {
    this.validateHash(criteriaHash);
    const distinctIds = [...new Set(ids.filter((id) => Number.isSafeInteger(id) && id > 0))];
    return this.materialize(criteriaHash, distinctIds);
  }

  createAllResults(criteria: SearchCriteria, criteriaHash: string): Selection {
    if (criteriaHash !== computeCriteriaHash(criteria)) throw new SelectionCriteriaHashError();
    return this.materialize(criteriaHash, this.search.matchingIds(criteria));
  }

  get(id: string): Selection | null {
    const row = this.row(id);
    if (!row) return null;
    if (isExpired(row, this.now().toISOString())) {
      this.database.prepare("DELETE FROM selection_sets WHERE id = ?").run(id);
      throw new SelectionExpiredError();
    }
    return toSelection(row);
  }

  clear(id: string): void {
    this.database.prepare("DELETE FROM selection_sets WHERE id = ?").run(id);
    this.cleanupExpired();
  }

  cleanupExpired(exceptId?: string): number {
    const now = this.now().toISOString();
    const result = exceptId
      ? this.database
          .prepare("DELETE FROM selection_sets WHERE expires_at <= ? AND id <> ?")
          .run(now, exceptId)
      : this.database.prepare("DELETE FROM selection_sets WHERE expires_at <= ?").run(now);
    return result.changes;
  }

  /** Runs the action and one-time selection deletion in one database transaction. */
  consume<T>(id: string, action: (selection: ConsumedSelection) => T): T {
    this.cleanupExpired(id);
    const now = this.now().toISOString();
    const consume = this.database.transaction(
      (): { status: "expired" } | { status: "complete"; value: T } => {
        const row = this.row(id);
        if (!row) throw new SelectionNotFoundError();
        if (isExpired(row, now)) {
          this.database.prepare("DELETE FROM selection_sets WHERE id = ?").run(id);
          return { status: "expired" };
        }
        const bookmarkIds = (
          this.database
            .prepare(
              "SELECT bookmark_id FROM selection_items WHERE selection_id = ? ORDER BY bookmark_id",
            )
            .all(id) as Array<{ bookmark_id: number }>
        ).map(({ bookmark_id }) => bookmark_id);
        const value = action({
          id: row.id,
          criteriaHash: row.criteria_hash,
          selectedCount: row.selected_count,
          bookmarkIds,
        });
        this.database.prepare("DELETE FROM selection_sets WHERE id = ?").run(id);
        return { status: "complete", value };
      },
    );
    const result = consume.immediate();
    if (result.status === "expired") throw new SelectionExpiredError();
    return result.value;
  }

  private materialize(criteriaHash: string, ids: readonly number[]): Selection {
    this.cleanupExpired();
    const createdAt = this.now();
    const expiresAt = new Date(createdAt.getTime() + this.ttlMs);
    const id = this.token();
    if (id.length < 32) throw new Error("Selection token source returned an unsafe token.");

    const create = this.database.transaction(() => {
      this.database
        .prepare(`
          INSERT INTO selection_sets(id, criteria_hash, selected_count, created_at, expires_at)
          VALUES (?, ?, 1, ?, ?)
        `)
        .run(id, criteriaHash, createdAt.toISOString(), expiresAt.toISOString());
      const insert = this.database.prepare(`
        INSERT OR IGNORE INTO selection_items(selection_id, bookmark_id)
        SELECT ?, id FROM bookmarks WHERE id = ?
      `);
      for (const bookmarkId of ids) insert.run(id, bookmarkId);
      const selectedCount = (
        this.database
          .prepare("SELECT count(*) AS count FROM selection_items WHERE selection_id = ?")
          .get(id) as { count: number }
      ).count;
      if (selectedCount === 0) throw new EmptySelectionError();
      this.database
        .prepare("UPDATE selection_sets SET selected_count = ? WHERE id = ?")
        .run(selectedCount, id);
      return toSelection(this.row(id) as SelectionRow);
    });
    return create.immediate();
  }

  private validateHash(criteriaHash: string): void {
    if (!HASH_PATTERN.test(criteriaHash)) throw new SelectionCriteriaHashError();
  }

  private row(id: string): SelectionRow | undefined {
    return this.database.prepare("SELECT * FROM selection_sets WHERE id = ?").get(id) as
      | SelectionRow
      | undefined;
  }
}
import type {
  Bookmark,
  BookmarkPage,
  MetadataStatus,
  Provenance,
  Scope,
  SortOrder,
} from "../../shared/contracts/api.js";
import { parseSearchQueryOrThrow } from "../../shared/search/parser.js";
import type { AppDatabase } from "../db/database.js";
import {
  compileSearchAst,
  normalizeSearchText,
  normalizeTagFilter,
