export interface SearchRequest {
  scope: Scope;
  query: string;
  tags: readonly string[];
  favorite?: boolean | null;
  unread?: boolean | null;
  sort: SortOrder;
  cursor?: string;
  limit?: number;
}

interface BookmarkRow {
  id: number;
  address: string;
  normalized_address: string;
  address_revision: number;
  title: string;
  title_sort_key: string;
  title_provenance: Provenance;
  retrieved_title_candidate: string | null;
  description: string;
  description_provenance: Provenance;
  retrieved_description_candidate: string | null;
  icon_hash: string | null;
  metadata_status: MetadataStatus;
  metadata_error_code: string | null;
  metadata_fetched_at: string | null;
  note_markdown: string;
  note_plain: string;
  is_favorite: 0 | 1;
  is_unread: 0 | 1;
  archived_at: string | null;
  created_at: string;
  updated_at: string;
}

interface CursorPayload {
  v: 1;
  sort: SortOrder;
  key: string;
  id: number;
}

interface SearchSql {
  withClause: string;
  fromClause: string;
  whereClause: string;
  parameters: unknown[];
}

const SORT_SQL: Record<SortOrder, string> = {
  created_desc: "b.created_at DESC, b.id DESC",
  created_asc: "b.created_at ASC, b.id ASC",
  updated_desc: "b.updated_at DESC, b.id DESC",
  title_asc: "b.title_sort_key ASC, b.id ASC",
};

export class InvalidSearchCursorError extends Error {
  constructor() {
    super("The search cursor is invalid or does not match the current sort.");
    this.name = "InvalidSearchCursorError";
  }
}

function cursorKey(row: BookmarkRow, sort: SortOrder): string {
  if (sort === "created_desc" || sort === "created_asc") return row.created_at;
  if (sort === "updated_desc") return row.updated_at;
  return row.title_sort_key;
}

function encodeCursor(row: BookmarkRow, sort: SortOrder): string {
  const payload: CursorPayload = { v: 1, sort, key: cursorKey(row, sort), id: row.id };
  return Buffer.from(JSON.stringify(payload), "utf8").toString("base64url");
}

function decodeCursor(value: string, sort: SortOrder): CursorPayload {
  try {
    const parsed = JSON.parse(
      Buffer.from(value, "base64url").toString("utf8"),
    ) as Partial<CursorPayload>;
    if (
      parsed.v !== 1 ||
      parsed.sort !== sort ||
      typeof parsed.key !== "string" ||
      parsed.key.length === 0 ||
      !Number.isSafeInteger(parsed.id) ||
      (parsed.id ?? 0) < 1
    ) {
      throw new InvalidSearchCursorError();
    }
    return parsed as CursorPayload;
  } catch (error) {
    if (error instanceof InvalidSearchCursorError) throw error;
    throw new InvalidSearchCursorError();
  }
}

function cursorPredicate(
  sort: SortOrder,
  cursor: CursorPayload,
): { sql: string; values: unknown[] } {
  if (sort === "created_desc") {
    return {
      sql: "(b.created_at < ? OR (b.created_at = ? AND b.id < ?))",
      values: [cursor.key, cursor.key, cursor.id],
    };
  }
  if (sort === "created_asc") {
    return {
      sql: "(b.created_at > ? OR (b.created_at = ? AND b.id > ?))",
      values: [cursor.key, cursor.key, cursor.id],
    };
  }
  if (sort === "updated_desc") {
    return {
      sql: "(b.updated_at < ? OR (b.updated_at = ? AND b.id < ?))",
      values: [cursor.key, cursor.key, cursor.id],
    };
  }
  return {
    sql: "(b.title_sort_key > ? OR (b.title_sort_key = ? AND b.id > ?))",
    values: [cursor.key, cursor.key, cursor.id],
  };
}

function scopePredicate(scope: Scope): string {
  if (scope === "read_later") return "b.archived_at IS NULL AND b.is_unread = 1";
  if (scope === "archived") return "b.archived_at IS NOT NULL";
  return "b.archived_at IS NULL";
}

function toBookmark(row: BookmarkRow, tags: Bookmark["tags"]): Bookmark {
  return {
    id: row.id,
    address: row.address,
    title: row.title,
    titleProvenance: row.title_provenance,
    retrievedTitleCandidate: row.retrieved_title_candidate,
    description: row.description,
    descriptionProvenance: row.description_provenance,
    retrievedDescriptionCandidate: row.retrieved_description_candidate,
    iconUrl: row.icon_hash ? `/api/bookmarks/${row.id}/icon` : null,
    metadataStatus: row.metadata_status,
    metadataErrorCode: row.metadata_error_code,
    noteMarkdown: row.note_markdown,
    tags,
    favorite: row.is_favorite === 1,
    unread: row.is_unread === 1,
    archived: row.archived_at !== null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export class SearchRepository {
  constructor(private readonly database: AppDatabase) {
    this.database.function("search_normalize", { deterministic: true }, (value: unknown) =>
      normalizeSearchText(typeof value === "string" ? value : ""),
    );
    this.verifySearchSupport();
  }

  /** Fail clearly during startup if the migration/index is absent or unusable. */
  verifySearchSupport(): void {
    try {
      this.database
        .prepare("SELECT rowid FROM bookmark_search WHERE bookmark_search MATCH ? LIMIT 0")
        .all('"trigram capability probe"');
    } catch (error) {
      throw new Error(
        `SQLite FTS5 trigram search is unavailable: ${error instanceof Error ? error.message : "unknown error"}`,
        { cause: error },
      );
    }
  }

  search(criteria: SearchRequest): BookmarkPage {
    const limit = Math.max(1, Math.min(criteria.limit ?? 50, 100));
    const base = this.buildSql(criteria);
    const total = (
      this.database
        .prepare(
          `${base.withClause} SELECT count(*) AS count ${base.fromClause} ${base.whereClause}`,
        )
        .get(...base.parameters) as { count: number }
    ).count;

    const pageWhere: string[] = [];
    const pageParameters = [...base.parameters];
    if (criteria.cursor) {
      const predicate = cursorPredicate(
        criteria.sort,
        decodeCursor(criteria.cursor, criteria.sort),
      );
      pageWhere.push(predicate.sql);
      pageParameters.push(...predicate.values);
    }
    const cursorSql = pageWhere.length > 0 ? ` AND ${pageWhere.join(" AND ")}` : "";
    const fetched = this.database
      .prepare(
        `${base.withClause} SELECT b.* ${base.fromClause} ${base.whereClause}${cursorSql} ` +
          `ORDER BY ${SORT_SQL[criteria.sort]} LIMIT ?`,
      )
      .all(...pageParameters, limit + 1) as BookmarkRow[];

    const hasMore = fetched.length > limit;
    const rows = hasMore ? fetched.slice(0, limit) : fetched;
    const tagsByBookmark = this.tagsFor(rows.map(({ id }) => id));
    const items = rows.map((row) => toBookmark(row, tagsByBookmark.get(row.id) ?? []));

    return {
      items,
      total,
      nextCursor:
        hasMore && rows.length > 0
          ? encodeCursor(rows[rows.length - 1] as BookmarkRow, criteria.sort)
          : null,
    };
  }

  /** Full current result membership, used later to create stable bulk snapshots. */
  matchingIds(criteria: Omit<SearchRequest, "cursor" | "limit">): number[] {
    const base = this.buildSql(criteria);
    return (
      this.database
        .prepare(
          `${base.withClause} SELECT b.id ${base.fromClause} ${base.whereClause} ` +
            `ORDER BY ${SORT_SQL[criteria.sort]}`,
        )
        .all(...base.parameters) as Array<{ id: number }>
    ).map(({ id }) => id);
  }

  /** Replace one contentful FTS row with application-normalized field values. */
  synchronizeBookmark(bookmarkId: number): void {
    const row = this.database
      .prepare("SELECT id, title, address, description, note_plain FROM bookmarks WHERE id = ?")
      .get(bookmarkId) as
      | { id: number; title: string; address: string; description: string; note_plain: string }
      | undefined;
    if (!row) {
      this.database.prepare("DELETE FROM bookmark_search WHERE rowid = ?").run(bookmarkId);
      return;
    }

    const replace = this.database.transaction(() => {
      this.database.prepare("DELETE FROM bookmark_search WHERE rowid = ?").run(bookmarkId);
      this.database
        .prepare(
          "INSERT INTO bookmark_search(rowid, title, address, description, note_plain) VALUES (?, ?, ?, ?, ?)",
        )
        .run(
          row.id,
          normalizeSearchText(row.title),
          normalizeSearchText(row.address),
          normalizeSearchText(row.description),
          normalizeSearchText(row.note_plain),
        );
    });
    replace();
  }

  rebuildSearchIndex(): void {
    const ids = this.database.prepare("SELECT id FROM bookmarks ORDER BY id").all() as Array<{
      id: number;
    }>;
    const rebuild = this.database.transaction(() => {
      this.database.prepare("DELETE FROM bookmark_search").run();
      for (const { id } of ids) this.synchronizeBookmark(id);
    });
    rebuild();
  }

  private buildSql(criteria: Omit<SearchRequest, "cursor" | "limit">): SearchSql {
    const compiled = compileSearchAst(parseSearchQueryOrThrow(criteria.query));
    const withClause = `WITH search_matches(id) AS (${compiled.sql})`;
    const fromClause = "FROM bookmarks b JOIN search_matches m ON m.id = b.id";
    const predicates = [scopePredicate(criteria.scope)];
    const parameters: unknown[] = [...compiled.parameters];

    if (criteria.favorite !== null && criteria.favorite !== undefined) {
      predicates.push("b.is_favorite = ?");
      parameters.push(criteria.favorite ? 1 : 0);
    }
    if (criteria.unread !== null && criteria.unread !== undefined) {
      predicates.push("b.is_unread = ?");
      parameters.push(criteria.unread ? 1 : 0);
    }

    const tagKeys = [...new Set(criteria.tags.map(normalizeTagFilter))];
    if (tagKeys.length > 0) {
      predicates.push(`b.id IN (
        SELECT bt.bookmark_id
        FROM bookmark_tags bt
        JOIN tags t ON t.id = bt.tag_id
        WHERE t.name_key IN (${tagKeys.map(() => "?").join(", ")})
        GROUP BY bt.bookmark_id
        HAVING count(DISTINCT t.name_key) = ?
      )`);
      parameters.push(...tagKeys, tagKeys.length);
    }

    return {
      withClause,
      fromClause,
      whereClause: `WHERE ${predicates.join(" AND ")}`,
      parameters,
    };
  }

  private tagsFor(bookmarkIds: number[]): Map<number, Bookmark["tags"]> {
    const grouped = new Map<number, Bookmark["tags"]>();
    if (bookmarkIds.length === 0) return grouped;
    const rows = this.database
      .prepare(`
        SELECT bt.bookmark_id, t.id, t.display_name
        FROM bookmark_tags bt
        JOIN tags t ON t.id = bt.tag_id
        WHERE bt.bookmark_id IN (${bookmarkIds.map(() => "?").join(", ")})
        ORDER BY t.name_key, t.id
      `)
      .all(...bookmarkIds) as Array<{ bookmark_id: number; id: number; display_name: string }>;
    for (const row of rows) {
      const tags = grouped.get(row.bookmark_id) ?? [];
      tags.push({ id: row.id, name: row.display_name });
      grouped.set(row.bookmark_id, tags);
    }
    return grouped;
  }
}
# Quickstart and Validation Guide

This guide defines how the completed implementation will be built, run, and verified. Commands become runnable during the implementation phase; no application code exists at the planning gate.

## Prerequisites

- Node.js 24.x and npm 11.x
- The shared Playwright Chromium installation at `/opt/playwright-browsers`
- A writable local `data/` directory for the SQLite database
- Port 4000 available

## Install and Verify

```bash
npm ci
npm run format:check
npm run lint
npm run typecheck
npm run test:unit
npm run test:integration
npm run test:performance
npm run build
npm run test:e2e
```

The project pins `@playwright/test` to `1.61.0`; do not download another browser revision.

Expected verification outcomes:

- Pure search, normalization, note, and metadata rules pass unit tests.
- API/SQLite integration tests use isolated temporary databases and deterministic network fixtures.
- The seeded 10,000-bookmark search suite meets the one-second p95 criterion.
- A 1,000-bookmark tag-changing bulk action finishes within ten seconds and changes no out-of-selection row.
- The production build completes before runtime presentation.

## Run the Prepared Application

```bash
npm start
```

The foreground server must:

- apply pending migrations before accepting requests;
- bind to `0.0.0.0:4000`;
- serve the JSON API under `/api` and the built client at `/`;
- mark the loaded application shell with `data-harness-ready="true"` only after initial data has loaded or a valid empty state is visible.

Review from the client environment at `http://maker:4000/`. Automated browser checks use `http://127.0.0.1:4000/`.

After dependencies, tests, and the production build succeed, implementation must create:

```json
{"kind":"application","port":4000,"path":"/","start_command":["npm","start"],"start_cwd":"/work"}
```

at `/work/.harness/app.json`.

## End-to-End Validation

### 1. Address-Only Capture and Duplicate Prevention

1. Paste a deterministic fixture-page address and save immediately without typing a title.
2. Confirm a readable fallback and pending state appear immediately.
3. Confirm title, description, and app-origin icon appear when metadata completes.
4. Edit the title, refresh metadata, and confirm the manual title is not replaced.
5. Paste a normalized equivalent of the same address.
6. Confirm no row is created and the existing bookmark opens in edit mode.
7. Repeat after archiving it; confirm the archived match opens and can be restored.

Metadata E2E uses a deterministic injected fixture provider. Separate integration tests prove the production network policy; the browser suite does not depend on public sites.

### 2. Search, Filters, and Sort

1. Seed records with overlapping fields and tags.
2. Verify ordinary adjacent terms use `AND` across fields.
3. Verify `OR`, quoted phrases, `#tag`, and `#"multiword tag"` against [search-grammar.md](./contracts/search-grammar.md).
4. Select multiple tag filters and confirm every selected tag is required.
5. Combine favorite/read state with search and tags.
6. Verify all four sort orders.
7. Enter unmatched quotes and missing operands; confirm position-aware guidance and no data mutation.

### 3. Read Later and Archive Restoration

1. Mark both favorite and non-favorite bookmarks for Read Later.
2. Confirm both appear in Read Later independently of favorite state.
3. Mark one read and confirm it leaves Read Later but remains active.
4. Archive the other and confirm it leaves Read Later while remaining unread.
5. Restore it and confirm it returns to Read Later with favorite and unread states intact.

### 4. Organization and Formatted Notes

1. Edit title, description, tags, favorite state, and note.
2. Use each supported note construct: heading, bold, italic, ordered list, unordered list, link, and inline code.
3. Confirm rendered output contains only supported elements and visible note text is searchable.
4. Exercise raw HTML, image syntax, and unsafe link fixtures; confirm none creates executable or embedded content.

### 5. Stable Bulk Actions

1. Create a filtered result spanning more than one rendered page.
2. Select all results and record the server-confirmed count.
3. Cause a pending metadata update that would otherwise alter the live result.
4. Apply add/remove tag, favorite/unfavorite, read/unread, archive/restore, and delete actions in isolated cases.
5. Confirm only the original snapshot members change.
6. Change the view with an active selection and confirm the selection clears.
7. Confirm bulk deletion shows the stable count and does nothing when cancelled.

### 6. Individual Edit and Delete

1. Edit every editable field and reload the app.
2. Change the address to one already saved and confirm the edited row keeps its old address while the existing match opens.
3. Cancel deletion and confirm no change.
4. Confirm deletion and verify the bookmark disappears from all scopes and live saved-view results.

### 7. Saved Views

1. Configure query, multiple tags, status filters, scope, and sort.
2. Save with a unique name, then change the collection.
3. Reopen the saved view and confirm the criteria are restored against current data.
4. Rename and update it.
5. Remove the last use of a referenced tag and confirm the view remains editable with an empty result.
6. Cancel and then confirm saved-view deletion; bookmarks must remain unchanged.

## Accessibility and Responsive Checks

- Complete every core flow using only the keyboard.
- Confirm focus is visible, dialogs trap and restore focus correctly, and status/error changes are announced.
- Run Axe on empty, populated, filtered, detail/edit, saved-view, and bulk-confirmation states.
- Repeat representative workflows at 320 CSS pixels and a standard desktop width with no horizontal page scrolling.
- Verify external bookmark destinations open without replacing the manager.

## Security-Specific Checks

- Confirm metadata requests deny direct and DNS-resolved loopback, private, link-local, multicast, reserved, and cloud-metadata destinations.
- Confirm every redirect and icon candidate is revalidated and DNS-pinned.
- Confirm time, redirect, decoded-byte, media-type, and image-dimension limits abort safely.
- Confirm the browser never requests remote site icons directly.
- Confirm metadata failures expose friendly categories without internal IP addresses or stack traces.
- Confirm all mutation routes reject invalid schemas and inappropriate cross-origin requests.

